        "content": [
          "## PURPOSE\n",
          "- Analistas de credito acompanhando portabilidade (CTC) e mercado de cessao (C3).\n",
          "## DISAMBIGUATION\n",
          "- 'Retencao' = status_pedido 'Retida pelo credor original'. 'SLA' = sla_resposta_cumprido (prazo de 120h).\n",
          "- Filtro por CNPJ em C3 usa c3_cessoes.cnpj_originador_principal.\n",
          "## Instructions you must follow when providing summaries\n",
          "- Taxas em % com uma casa decimal; valores em R$ com duas casas.\n"
        ]
      }
    ],
    "example_question_sqls": [
      {
        "id": "6d0beb47294158ca925e15cef14cce21",
        "question": [
          "Taxa de retencao por credor original"
        ],
        "sql": [
          "SELECT participantes.nome_participante, count(*) AS pedidos, round(avg(CASE WHEN ctc_portabilidades.status_pedido = 'Retida pelo credor original' THEN 1 ELSE 0 END), 3) AS taxa_retencao FROM workshop_nuclea_genie_catalog.credito.ctc_portabilidades ctc_portabilidades JOIN workshop_nuclea_genie_catalog.cadastro.participantes participantes ON participantes.ispb = ctc_portabilidades.ispb_credor_original GROUP BY ALL HAVING count(*) > 200 ORDER BY taxa_retencao DESC LIMIT 15"
        ]
      }
    ],
